#!/usr/bin/env python3
"""make_icon.py — 앱 아이콘 만들기 (달력 숫자 = 오늘 날짜)

  사용: python3 build/make_icon.py <출력.svg> [일자]
        python3 build/make_icon.py icon-maskable.svg --maskable [일자]
        python3 build/make_icon.py icon-ios.svg --ios [일자]   (아이폰 홈 화면용)
        일자를 안 주면 오늘 날짜를 쓴다.

글자를 <text> 로 두면 그리는 쪽(브라우저·서버)에 그 글꼴이 없을 때
네모(두부)로 나온다. 그래서 '봉화·오늘·숫자' 를 미리 도형(path)으로 바꿔
아래 표에 담아 두었다 — 글꼴이 하나도 없는 곳에서도 똑같이 그려진다.

바탕화면에 이미 만들어 둔 아이콘은 OS가 그때의 그림을 계속 쓰므로 바뀌지 않는다.
이 파일이 하는 일은 '앞으로 새로 설치하는 사람'이 오늘 날짜를 보게 하는 것이다.
(화면 안 파비콘은 앱이 매일 스스로 다시 그린다.)
"""
import sys, datetime

UPM = 1000
GLYPH = {'봉': {'d': 'M835 287V392H497V448H728V791H594V716H272V792H138V448H366V392H30V287ZM746 91C746 192 629 255 431 255C235 255 118 192 118 91C118 -6 235 -72 433 -72C629 -72 746 -6 746 91ZM609 89C609 56 539 28 431 28C326 28 256 56 256 89C256 126 326 153 431 153C539 153 609 126 609 89ZM594 552H272V614H594Z', 'w': 865}, '화': {'d': 'M526 359C526 447 436 515 305 515C172 515 84 447 84 359C84 287 144 228 239 209V160C163 157 86 157 20 158C25 121 31 81 37 45C193 45 376 54 575 79L568 181C515 174 446 168 370 165V209C465 228 526 287 526 359ZM743 812H612V-79H743V348H850V456H743ZM562 535V634H48V535ZM182 668H436V767H182ZM391 359C391 325 354 300 305 300C255 300 219 325 219 359C219 393 255 421 305 421C354 421 391 393 391 359Z', 'w': 865}, '오': {'d': 'M835 30V135H498V272C661 291 764 387 764 517C764 663 633 765 432 765C232 765 101 663 101 517C101 388 203 292 365 272V135H30V30ZM629 516C629 430 550 371 432 371C312 371 235 430 235 516C235 602 312 659 432 659C552 659 629 602 629 516Z', 'w': 865}, '늘': {'d': 'M738 518V621H274V796H140V518ZM835 363V468H30V363ZM761 -79V30H258V72H729V311H129V208H596V164H129V-79Z', 'w': 865}, '0': {'d': 'M321 29C468 29 597 119 597 366V401C597 645 470 738 323 738C179 738 46 647 46 398V362C46 125 167 29 321 29ZM321 135C234 135 195 210 195 365V408C195 564 236 632 322 632C407 632 450 560 450 401V358C450 198 408 135 321 135Z', 'w': 652}, '1': {'d': 'M141 37H284V730H211L29 650V567L141 588Z', 'w': 375}, '2': {'d': 'M48 41H492V150H230L301 222C371 295 490 417 490 541C490 667 412 738 254 738C174 738 104 716 56 689L74 588C112 608 169 629 212 629C297 629 343 602 343 521C343 440 261 350 167 250L48 123Z', 'w': 536}, '3': {'d': 'M236 31C395 31 489 109 489 238C489 339 431 389 345 405C420 432 466 485 466 567C466 679 383 738 253 738C182 738 97 722 53 699L68 596C108 613 165 628 214 628C286 628 326 605 326 542C326 481 280 449 205 447L138 445V346L213 344C294 342 340 317 340 248C340 176 295 141 211 141C158 141 81 158 47 179L25 79C65 54 152 31 236 31Z', 'w': 536}, '4': {'d': 'M328 27H462V163H566V265H462V730H369L19 239V163H328ZM164 265 329 496V265Z', 'w': 602}, '5': {'d': 'M229 31C388 31 483 130 483 260C483 407 399 479 260 479C236 479 199 474 180 467L190 620H449V727H85L59 339C91 355 156 377 197 377C288 377 337 343 337 262C337 185 282 145 191 145C140 145 94 163 55 183L31 77C77 51 150 31 229 31Z', 'w': 519}, '6': {'d': 'M305 29C464 29 546 135 546 268C546 399 462 473 342 473C273 473 218 445 184 417C194 578 263 625 358 625C405 625 462 609 490 595L514 699C484 716 422 737 353 737C186 737 44 646 44 381V334C44 147 133 29 305 29ZM302 131C219 131 185 198 185 310V316C207 345 254 375 298 375C363 375 412 343 412 257C412 176 369 131 302 131Z', 'w': 587}, '7': {'d': 'M94 41H250L491 645V727H39V618H337Z', 'w': 526}, '8': {'d': 'M299 29C469 29 567 112 567 230C567 325 499 376 420 404C492 436 540 493 540 565C540 674 451 738 300 738C149 738 55 665 55 554C55 470 102 424 172 391C97 361 36 299 36 214C36 104 127 29 299 29ZM295 128C213 128 165 166 165 228C165 283 220 328 279 348C375 326 426 288 426 223C426 167 377 128 295 128ZM317 449C233 468 195 503 195 558C195 607 235 638 302 638C376 638 411 603 411 554C411 503 366 468 317 449Z', 'w': 602}, '9': {'d': 'M270 737C111 737 36 634 36 495C36 363 119 283 240 283C309 283 364 310 398 338C392 170 322 141 227 141C180 141 115 161 87 176L67 73C99 54 166 29 235 29C402 29 538 108 538 385V432C538 627 442 737 270 737ZM274 636C360 636 397 565 397 456V440C376 411 327 382 283 382C218 382 170 420 170 507C170 587 206 636 274 636Z', 'w': 587}}

def txt(s, cx, baseline, size, fill, tracking=0):
    """글자를 가운데 맞춤으로 놓는다. tracking 은 글자 사이 벌림(px, 음수면 좁힘)."""
    k = size / UPM
    adv = [GLYPH[c]['w'] * k for c in s]
    total = sum(adv) + tracking * (len(s) - 1)
    x = cx - total / 2
    out = []
    for c, a in zip(s, adv):
        out.append(f'<path d="{GLYPH[c]["d"]}" fill="{fill}" '
                   f'transform="translate({x:.2f} {baseline}) scale({k:.5f} {-k:.5f})"/>')
        x += a + tracking
    return '\n  '.join(out)

def build(day, maskable=False, ios=False):
    # 아이폰은 제 손으로 모서리를 둥글린다. 우리가 미리 둥글려 두면 그 바깥이
    # 투명 → 검정으로 깔려 귀퉁이에 검은 조각이 남는다. 그래서 ios 는 네모 그대로.
    # 안드로이드 마스커블처럼 줄이지도 않는다(아이폰은 귀퉁이만 깎는다).
    rx   = '' if (maskable or ios) else ' rx="112"'
    open_g  = '<g transform="translate(256 256) scale(.82) translate(-256 -256)">' if maskable else ''
    close_g = '</g>' if maskable else ''
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">
 <defs>
  <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
   <stop offset="0" stop-color="#22C55E"/><stop offset="1" stop-color="#16A34A"/></linearGradient>
  <clipPath id="round"><rect width="512" height="512"{rx}/></clipPath>
 </defs>
 <rect width="512" height="512"{rx} fill="url(#bg)"/>
 {open_g}
 <!-- 배경: 해와 산 (종 뒤로 살짝) -->
 <g clip-path="url(#round)">
  <circle cx="62" cy="68" r="30" fill="#F4B324"/>
  <path d="M-20 330 L44 262 L100 314 L160 258 L226 330 L226 420 L-20 420Z" fill="#0F7A38" opacity=".42"/>
  <path d="M-20 372 L36 322 L92 366 L146 320 L210 378 L210 430 L-20 430Z" fill="#0F7A38" opacity=".28"/>
 </g>

 <!-- 반짝임 -->
 <g stroke="#F4B324" stroke-width="19" stroke-linecap="round">
  <path d="M446 74 L436 112"/><path d="M488 116 L456 144"/>
 </g>

 <!-- 종 (봉화 글씨를 넉넉히 감싸도록 크게) -->
 <rect x="240" y="58" width="32" height="38" rx="16" fill="#fff"/>
 <path d="M256 84c-84 0-124 92-132 186-4 44-14 70-28 92h320c-14-22-24-48-28-92-8-94-48-186-132-186Z" fill="#fff"/>
 <rect x="72" y="358" width="368" height="48" rx="24" fill="#fff"/>
 <path d="M100 360H412" stroke="#16A34A" stroke-width="7" stroke-linecap="round" opacity=".22"/>
 <rect x="248" y="400" width="16" height="34" rx="8" fill="#F4B324"/>
 <circle cx="256" cy="458" r="30" fill="#F4B324"/>

 {txt('봉화', 256, 318, 132, '#16A34A', -6)}

 <!-- 오늘 날짜 -->
 <g>
  <rect x="286" y="310" width="202" height="180" rx="28" fill="#fff"/>
  <path d="M286 338a28 28 0 0 1 28-28h146a28 28 0 0 1 28 28v34H286Z" fill="#F4B324"/>
  <rect x="330" y="290" width="17" height="38" rx="8" fill="#0F7A38"/>
  <rect x="427" y="290" width="17" height="38" rx="8" fill="#0F7A38"/>
  {txt('오늘', 387, 362, 30, '#fff')}
  {txt(day, 387, 462, 94, '#16A34A')}
 </g>
 {close_g}
</svg>
'''

if __name__ == '__main__':
    flags = {'--maskable', '--ios'}
    args = [a for a in sys.argv[1:] if a not in flags]
    maskable = '--maskable' in sys.argv[1:]
    ios      = '--ios' in sys.argv[1:]
    out = args[0] if args else 'icon.svg'
    day = args[1] if len(args) > 1 else str(datetime.date.today().day)
    open(out, 'w', encoding='utf-8').write(build(day, maskable, ios))
    kind = ', 마스커블' if maskable else (', 아이폰용' if ios else '')
    print(f'{out} 생성 (달력 숫자: {day}{kind})')
